import Foundation
import Providers

/// Executable stand-ins for the provider CLIs. They answer `--version` with a matrix version,
/// record their argv/environment/stdin in `$TMPDIR`, and speak the protocol. The Claude event
/// shapes are synthetic (no published schema); the Codex messages are checked against the
/// schema generated by codex-cli 0.170.0.
public enum FixturePrograms {
    /// One step of a scripted Claude run.
    public enum ClaudeStep {
        case emit(JSONValue)
        /// A line that is not JSON.
        case raw(String)
        case sleep(seconds: Double)
        /// Writes a file relative to the working directory (stands in for an Edit tool call).
        case writeFile(String, String)
        case stderr(String)
        case exit(Int32)
        /// Waits until interrupted; SIGINT prints an `error_during_execution` result.
        case waitForInterrupt
        /// Prints its start and end time around a pause, for overlap checks.
        case timestamped(seconds: Double)
        /// Ignores SIGINT and SIGTERM, then waits (only SIGKILL ends it).
        case ignoreInterrupts
    }

    public static func makeExecutable(_ script: String, in directory: String, name: String) throws -> String {
        let path = directory + "/" + name
        try script.write(toFile: path, atomically: true, encoding: .utf8)
        chmod(path, 0o755)
        return path
    }

    public static func claude(_ steps: [ClaudeStep]) -> String {
        var body = ""
        for step in steps {
            switch step {
            case .emit(let value): body += "say(\(perlString(value.description)));\n"
            case .raw(let text): body += "say(\(perlString(text)));\n"
            case .sleep(let seconds): body += "sleep(\(seconds));\n"
            case .writeFile(let path, let content):
                body += "{ open(my $f, '>', \(perlString(path))) or die; print $f \(perlString(content)); close $f; }\n"
            case .stderr(let text): body += "print STDERR \(perlString(text)), \"\\n\";\n"
            case .exit(let code): body += "exit(\(code));\n"
            case .waitForInterrupt: body += "while (1) { sleep(0.05); }\n"
            case .ignoreInterrupts:
                body += "$SIG{INT} = 'IGNORE'; $SIG{TERM} = 'IGNORE'; while (1) { sleep(0.05); }\n"
            case .timestamped(let seconds):
                body += "open(my $t, '>>', \"$tmp/times\"); printf $t \"%.3f\\n\", time; sleep(\(seconds)); printf $t \"%.3f\\n\", time; close $t;\n"
            }
        }
        return """
            #!/usr/bin/perl
            use strict; use warnings; use JSON::PP; use Time::HiRes qw(sleep time);
            $| = 1;
            if (@ARGV && $ARGV[0] eq '--version') { print "2.1.328 (Claude Code)\\n"; exit 0; }
            my $tmp = $ENV{TMPDIR} // '/tmp';
            my $prompt = do { local $/; <STDIN> };
            { open(my $a, '>', "$tmp/received.json") or die; print $a JSON::PP->new->canonical->encode({argv => \\@ARGV, env => \\%ENV, prompt => $prompt, exe => $0}); close $a; }
            sub say { print $_[0], "\\n"; }
            $SIG{INT} = sub { say('{"type":"result","subtype":"error_during_execution","is_error":true,"session_id":"s-fixture"}'); exit 130; };
            \(body)
            exit 0;
            """
    }

    public enum CodexScenario: String {
        /// Full turn: agent message, file change approval, token usage, completed.
        case success
        /// The turn waits until `turn/interrupt`, then completes as interrupted.
        case interruptible
        /// `thread/start` is answered with an error (before any turn).
        case threadStartError
        /// The server asks for user input and for extra permissions before completing.
        case unusualRequests
        /// Like `success`, but the process exits without `turn/completed`.
        case dropsAfterApproval
        /// Reads `initialize` and never answers.
        case silentInitialize
        /// Reads `turn/start` and never answers.
        case turnStartHangs
        /// Receives `turn/start`, changes the worktree and crashes without answering.
        case crashAfterTurnStart
        /// Completes the turn with a status that is not terminal.
        case unknownTurnStatus
        /// Announces a file change outside the worktree and asks to approve it.
        case outsideChange
        /// Announces a change inside the worktree, then widens the patch to a path outside.
        case widenedChange
    }

    public static func codex(_ scenario: CodexScenario, file: String = "codex.txt", pauseSeconds: Double = 0) -> String {
        """
        #!/usr/bin/perl
        use strict; use warnings; use JSON::PP; use Time::HiRes qw(sleep time);
        $| = 1;
        if (@ARGV && $ARGV[0] eq '--version') { print "codex-cli 0.170.0\\n"; exit 0; }
        my $scenario = '\(scenario.rawValue)';
        $SIG{INT} = sub { print STDERR "closing"; exit 0; };
        my $tmp = $ENV{TMPDIR} // '/tmp';
        my $json = JSON::PP->new->canonical->allow_nonref;
        { open(my $a, '>', "$tmp/received.json") or die; print $a $json->encode({argv => \\@ARGV, env => \\%ENV, exe => $0}); close $a; }
        open(my $log, '>>', "$tmp/client.jsonl") or die;
        sub send_msg { print $json->encode($_[0]), "\\n"; }
        my ($thread, $turn, $cwd) = ('thr-1', 'turn-1', '/');
        my $true = JSON::PP::true; my $false = JSON::PP::false;
        my $next_server_id = 100;
        sub read_msg { my $line = <STDIN>; return undef unless defined $line; print $log $line; return $json->decode($line); }
        sub wait_response { my ($id) = @_; while (my $m = read_msg()) { return $m if defined $m->{id} && !defined $m->{method} && $m->{id} eq $id; } return undef; }
        sub server_request { my ($method, $params) = @_; my $id = $next_server_id++; send_msg({id => $id, method => $method, params => $params}); return wait_response($id); }
        sub note { send_msg({method => $_[0], params => $_[1]}); }
        sub turn_obj { return {id => $turn, items => [], status => $_[0]}; }
        sub finish_turn { note('turn/completed', {threadId => $thread, turn => turn_obj($_[0])}); }
        while (my $m = read_msg()) {
            my $method = $m->{method} // ''; my $id = $m->{id};
            if ($method eq 'initialize') {
                next if $scenario eq 'silentInitialize';
                send_msg({id => $id, result => {codexHome => "$tmp/codex-home", platformFamily => 'unix', platformOs => 'macos', userAgent => 'kaiorx-fixture/0.170.0'}});
            } elsif ($method eq 'thread/start') {
                if ($scenario eq 'threadStartError') { send_msg({id => $id, error => {code => -32000, message => 'not signed in'}}); next; }
                $cwd = $m->{params}{cwd};
                send_msg({id => $id, result => {approvalPolicy => 'on-request', approvalsReviewer => 'user', cwd => $cwd, model => $m->{params}{model},
                    modelProvider => 'openai', sandbox => {type => 'workspaceWrite', writableRoots => [$cwd], networkAccess => $false},
                    thread => {cliVersion => '0.170.0', createdAt => 0, cwd => $cwd, ephemeral => $true, id => $thread, modelProvider => 'openai',
                        preview => '', projectId => undef, sessionId => 'sess-1', source => 'appServer', status => {type => 'idle'}, turns => [], updatedAt => 0}}});
            } elsif ($method eq 'turn/start') {
                next if $scenario eq 'turnStartHangs';
                if ($scenario eq 'crashAfterTurnStart') { open(my $f, '>', "$cwd/side-effect.txt"); close $f; print STDERR "fixture crash: turn aborted\n"; print STDERR "no newline at end"; exit(1); }
                send_msg({id => $id, result => {turn => turn_obj('inProgress')}});
                note('turn/started', {threadId => $thread, turn => turn_obj('inProgress')});
                if ($scenario eq 'interruptible') { next; }
                note('item/started', {threadId => $thread, turnId => $turn, startedAtMs => 1, item => {type => 'agentMessage', id => 'msg-1', text => ''}});
                note('item/agentMessage/delta', {threadId => $thread, turnId => $turn, itemId => 'msg-1', delta => 'Hallo '});
                note('item/agentMessage/delta', {threadId => $thread, turnId => $turn, itemId => 'msg-1', delta => 'Welt'});
                note('item/completed', {threadId => $thread, turnId => $turn, completedAtMs => 2, item => {type => 'agentMessage', id => 'msg-1', text => 'Hallo Welt'}});
                if ($scenario eq 'unusualRequests') {
                    server_request('item/tool/requestUserInput', {threadId => $thread, turnId => $turn, itemId => 'q-1', isBlocking => $true,
                        questions => [{id => 'q', header => 'Frage', question => 'Weiter?'}]});
                    server_request('item/permissions/requestApproval', {threadId => $thread, turnId => $turn, itemId => 'p-1', startedAtMs => 3,
                        cwd => $cwd, permissions => {network => {enabled => $true}}});
                    server_request('item/commandExecution/requestApproval', {threadId => $thread, turnId => $turn, itemId => 'c-1', startedAtMs => 4,
                        command => 'curl example.com'});
                    finish_turn('completed');
                    next;
                }
                if (\(pauseSeconds) > 0) { open(my $t, '>>', "$tmp/times"); printf $t "%.3f\\n", time; sleep(\(pauseSeconds)); printf $t "%.3f\\n", time; close $t; }
                my $target = $scenario eq 'outsideChange' ? '../escape.txt' : '\(file)';
                my $change = {type => 'fileChange', id => 'fc-1', status => 'inProgress', changes => [{path => $target, kind => {type => 'add'}, diff => "+codex\\n"}]};
                note('item/started', {threadId => $thread, turnId => $turn, startedAtMs => 3, item => $change});
                if ($scenario eq 'widenedChange') {
                    $target = '../escape.txt';
                    note('item/fileChange/patchUpdated', {threadId => $thread, turnId => $turn, itemId => 'fc-1',
                        changes => [{path => $target, kind => {type => 'add'}, diff => "+x\\n"}]});
                }
                my $answer = server_request('item/fileChange/requestApproval', {threadId => $thread, turnId => $turn, itemId => 'fc-1', startedAtMs => 3});
                my $accepted = $answer && $answer->{result} && $answer->{result}{decision} eq 'accept';
                if ($accepted) { open(my $f, '>', "$cwd/$target") or die; print $f "codex\\n"; close $f; }
                $change->{status} = $accepted ? 'completed' : 'declined';
                note('item/completed', {threadId => $thread, turnId => $turn, completedAtMs => 4, item => $change});
                if ($scenario eq 'dropsAfterApproval') { exit(0); }
                my $usage = {cachedInputTokens => 2, inputTokens => 12, outputTokens => 7, reasoningOutputTokens => 0, totalTokens => 19};
                note('thread/tokenUsage/updated', {threadId => $thread, turnId => $turn, tokenUsage => {total => $usage, last => $usage}});
                finish_turn($scenario eq 'unknownTurnStatus' ? 'inProgress' : 'completed');
            } elsif ($method eq 'account/read') {
                print STDERR "account read\n";
                send_msg({id => $id, result => {account => {type => 'chatgpt', email => 'owner@example.org', planType => 'plus'}, requiresOpenaiAuth => $true}});
            } elsif ($method eq 'account/rateLimits/read') {
                send_msg({id => $id, error => {code => -32601, message => 'not in fixture'}});
            } elsif ($method eq 'turn/interrupt') {
                send_msg({id => $id, result => {}});
                finish_turn('interrupted');
            }
        }
        exit 0;
        """
    }

    /// Perl single-quoted string literal.
    static func perlString(_ text: String) -> String {
        "'" + text.replacingOccurrences(of: "\\", with: "\\\\").replacingOccurrences(of: "'", with: "\\'") + "'"
    }

    /// Path of a vendored Codex schema file.
    public static func codexSchema(_ name: String, file: String = #filePath) -> URL {
        URL(filePath: file).deletingLastPathComponent().deletingLastPathComponent()
            .appending(path: "ProvidersTests/Fixtures/codex-app-server-0.170.0/\(name)")
    }
}
